// Transaction boundary: every patch point and payload are valid before any writes.
for (const file of Object.values(paths)) backup(file);
writeText(paths.engine, payload.engine);
writeText(paths.worklet, payload.worklet);
writeText(paths.cpp, payload.cpp);
writeText(paths.build, payload.build);
writeText(paths.test, payload.test);
writeText(paths.compatWorklet, restoreEol(compat, compatRead.eol));
ensureParent(paths.wasm);
fs.writeFileSync(paths.wasm, nextWasm);
writeText(paths.player, restoreEol(player, playerRead.eol));
writeText(paths.mini, restoreEol(mini, miniRead.eol));

const installedWasm = fs.readFileSync(paths.wasm);
if (!installedWasm.equals(nextWasm)) fail("Installed WASM did not match the validated Phase 3.1 payload.");

console.log(`MVP Studio WASM V2 Phase 3.1 Volume Match applied successfully. (${INSTALLER_REVISION})`);
