console.log("  Measurement settling: ~2 seconds before correction begins.");
console.log("  Gain movement: slow 3 s down / 5 s up.");
console.log("  Compatibility Worklet receives the same target/dead-zone/cap behavior.");
console.log("Preserved: V1.1 EQ gain staging • V2 transient • V2 4-band multiband • final 4x peak guard.");
